-- SQL Quest practice dataset "cafe": Bean & Bloom Café
-- Generated by scripts/gen-datasets.mjs (deterministic) - edit the generator, not this file.

CREATE TABLE menu_items (
    item_id      integer PRIMARY KEY,
    name         text NOT NULL,
    category     text NOT NULL,
    price        numeric(5,2) NOT NULL CHECK (price > 0),
    calories     integer,
    is_vegan     boolean NOT NULL,
    is_available boolean NOT NULL,
    added_on     date NOT NULL
);

CREATE TABLE customers (
    customer_id    integer PRIMARY KEY,
    first_name     text NOT NULL,
    last_name      text NOT NULL,
    email          text,
    city           text NOT NULL,
    joined_on      date NOT NULL,
    loyalty_points integer NOT NULL DEFAULT 0 CHECK (loyalty_points >= 0)
);

CREATE TABLE staff (
    staff_id    integer PRIMARY KEY,
    name        text NOT NULL,
    role        text NOT NULL,
    hourly_rate numeric(5,2) NOT NULL CHECK (hourly_rate > 0),
    hired_on    date NOT NULL,
    manager_id  integer REFERENCES staff (staff_id)
);

CREATE TABLE orders (
    order_id       integer PRIMARY KEY,
    customer_id    integer REFERENCES customers (customer_id),
    item_id        integer NOT NULL REFERENCES menu_items (item_id),
    staff_id       integer NOT NULL REFERENCES staff (staff_id),
    quantity       integer NOT NULL CHECK (quantity > 0),
    order_time     timestamp NOT NULL,
    payment_method text NOT NULL,
    tip            numeric(4,2)
);





ANALYZE;
